// AddClassMedia adds the given related objects to the existing relationships
// of the class, optionally inserting them as new records.
// Appends related to o.R.ClassMedia.
// Sets related.R.Class appropriately.
func (o *Class) AddClassMedia(exec boil.Executor, insert bool, related ...*ClassMedium) error {
	var err error
	for _, rel := range related {
		if insert {
			rel.ClassID = o.ID
			if err = rel.Insert(exec, boil.Infer()); err != nil {
				return errors.Wrap(err, "failed to insert into foreign table")
			}
		} else {
			updateQuery := fmt.Sprintf(
				"UPDATE \"class_media\" SET %s WHERE %s",
				strmangle.SetParamNames("\"", "\"", 1, []string{"class_id"}),
				strmangle.WhereClause("\"", "\"", 2, classMediumPrimaryKeyColumns),
			)
			values := []any{o.ID, rel.ID}

			if boil.DebugMode {
				fmt.Fprintln(boil.DebugWriter, updateQuery)
				fmt.Fprintln(boil.DebugWriter, values)
			}
			if _, err = exec.Exec(updateQuery, values...); err != nil {
				return errors.Wrap(err, "failed to update foreign table")
			}

			rel.ClassID = o.ID
		}
	}

	if o.R == nil {
		o.R = &classR{
			ClassMedia: related,
		}
	} else {
		o.R.ClassMedia = append(o.R.ClassMedia, related...)
	}

	for _, rel := range related {
		if rel.R == nil {
			rel.R = &classMediumR{
				Class: o,
			}
		} else {
			rel.R.Class = o
		}
	}
	return nil
}

